def check_expression(expression):
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}

    for char in expression:
        if char in ['(', '[', '{']:
            stack.append(char)
        elif char in [')', ']', '}']:
            if not stack or bracket_map[char] != stack.pop():
                return False

    return len(stack) == 0

